    if source.line_by_match.is_some() { target.line_by_match = source.line_by_match; }
    if source.max_threads.is_some() { target.max_threads = source.max_threads; }
    if source.size_per_thread.is_some() { target.size_per_thread = source.size_per_thread; }
    if source.bin_check_bytes.is_some() { target.bin_check_bytes = source.bin_check_bytes; }
    if source.mmap_bytes.is_some() { target.mmap_bytes = source.mmap_bytes; }
}

fn load_config(is_ambs: bool) -> Config {
    let filename = if is_ambs { "ambs.toml" } else { "ambr.toml" };
    let hidden_filename = if is_ambs { ".ambs.toml" } else { ".ambr.toml" };

    let mut candidates = Vec::new();

    if let Some(home) = dirs::home_dir() {
        candidates.push(home.join(hidden_filename));
    }

    if let Some(config_dir) = dirs::config_dir() {
        candidates.push(config_dir.join("amber").join(filename));
    }

    candidates.push(PathBuf::from("/etc/amber").join(filename));

    let mut merged = Config::default();

    for path in candidates {
        if path.exists() {
            if let Ok(content) = fs::read_to_string(&path) {
                if let Ok(cfg) = toml::from_str::<Config>(&content) {
                    merge_config(&mut merged, cfg);
                }
            }
        }
    }

    merged
}

fn is_ambs_mode() -> bool {
