fn is_binary_file(path: &Path, bin_check_bytes: usize) -> bool {
    let mut file = match File::open(path) {
        Ok(f) => f,
        Err(_) => return false,
    };
    let mut buf = vec![0u8; bin_check_bytes];
    let n = match file.read(&mut buf) {
        Ok(n) => n,
        Err(_) => return false,
    };
    buf[..n].iter().any(|&b| b == 0)
}

fn main() {
    let is_ambs = is_ambs_mode();
    let bin_name = env::args().next().unwrap_or_else(|| "executable".to_string());
    let bin_stem = Path::new(&bin_name)
        .file_name()
        .and_then(|s| s.to_str())
        .unwrap_or("executable");

    let mut app = build_cli(bin_stem, is_ambs);
    let matches = match app.try_get_matches_from_mut(env::args()) {
        Ok(m) => m,
        Err(e) => {
            eprintln!("{}", e);
            process::exit(1);
        }
    };

    if matches.get_flag("help") {
        let mut help_app = build_cli(bin_stem, is_ambs);
        let _ = help_app.print_help();
        println!();
        process::exit(0);
    }

    if matches.get_flag("version") {
        println!("ambr 0.6.0");
        process::exit(0);
    }

    let cfg = load_config(is_ambs);

    let key_arg = matches.get_one::<String>("KEYWORD").unwrap().to_string();
    let key_from_file = matches.get_flag("key-from-file");
    let keyword = if key_from_file {
        fs::read_to_string(&key_arg).unwrap_or(key_arg)
    } else {
        key_arg
    };

    let rep_from_file = matches.get_flag("rep-from-file");
    let replacement = if !is_ambs {
        let rep_arg = matches.get_one::<String>("REPLACEMENT").cloned().unwrap_or_default();
        if rep_from_file {
            fs::read_to_string(&rep_arg).unwrap_or(rep_arg)
        } else {
            rep_arg
        }
    } else {
        String::new()
    };

    let raw_paths: Vec<PathBuf> = match matches.get_many::<String>("PATHS") {
        Some(vals) => vals.map(PathBuf::from).collect(),
        None => vec![PathBuf::from(".")],
    };

    let parse_num = |name: &str, default: usize| -> usize {
        matches.get_one::<String>(name).and_then(|s| s.parse().ok()).unwrap_or(default)
    };

    let opts = RunOptions {
        is_ambs,
        keyword,
        replacement,
        paths: raw_paths,
        regex: matches.get_flag("regex") || cfg.regex.unwrap_or(false),
        column: matches.get_flag("column") || cfg.column.unwrap_or(false),
        row: matches.get_flag("row") || cfg.row.unwrap_or(false),
        binary: matches.get_flag("binary") || cfg.binary.unwrap_or(false),
        statistics: matches.get_flag("statistics") || cfg.statistics.unwrap_or(false),
        skipped: matches.get_flag("skipped") || cfg.skipped.unwrap_or(false),
        interactive: if matches.get_flag("no-interactive") { false } else { cfg.interactive.unwrap_or(true) },
        recursive: if matches.get_flag("no-recursive") { false } else { cfg.recursive.unwrap_or(true) },
        symlink: if matches.get_flag("no-symlink") { false } else { cfg.symlink.unwrap_or(true) },
        color: if matches.get_flag("no-color") { false } else { cfg.color.unwrap_or(true) },
        file: if matches.get_flag("no-file") { false } else { cfg.file.unwrap_or(true) },
        skip_vcs: if matches.get_flag("no-skip-vcs") { false } else { cfg.skip_vcs.unwrap_or(true) },
        skip_gitignore: if matches.get_flag("no-skip-gitignore") { false } else { cfg.skip_gitignore.unwrap_or(true) },
        fixed_order: if matches.get_flag("no-fixed-order") { false } else { cfg.fixed_order.unwrap_or(true) },
        parent_ignore: if matches.get_flag("no-parent-ignore") { false } else { cfg.parent_ignore.unwrap_or(true) },
        preserve_time: matches.get_flag("preserve-time"),
        max_threads: parse_num("max-threads", cfg.max_threads.unwrap_or(20)),
        size_per_thread: parse_num("size-per-thread", cfg.size_per_thread.unwrap_or(1048576)),
        bin_check_bytes: parse_num("bin-check-bytes", cfg.bin_check_bytes.unwrap_or(256)),
        mmap_bytes: parse_num("mmap-bytes", cfg.mmap_bytes.unwrap_or(1048576)),
        key_from_file,
        rep_from_file,
        verbose: matches.get_flag("verbose"),
    };

    let start_time = Instant::now();

    let mut walk_builder = WalkBuilder::new(&opts.paths[0]);
    for p in &opts.paths[1..] {
        walk_builder.add(p);
    }

    walk_builder.hidden(false);
    walk_builder.parents(opts.parent_ignore);
    walk_builder.git_ignore(opts.skip_gitignore);
    walk_builder.git_exclude(opts.skip_gitignore);
    walk_builder.git_global(opts.skip_gitignore);
    walk_builder.ignore(opts.skip_gitignore);
    walk_builder.follow_links(opts.symlink);

    if !opts.recursive {
        walk_builder.max_depth(Some(1));
    }

    let skip_vcs = opts.skip_vcs;
    walk_builder.filter_entry(move |entry| {
        if skip_vcs {
            if let Some(name) = entry.file_name().to_str() {
                if name == ".git" || name == ".hg" || name == ".svn" || name == ".bzr" {
                    return false;
                }
            }
        }
        true
    });

    let walker = walk_builder.build();
    let mut files_to_process = Vec::new();

    for result in walker {
        match result {
            Ok(entry) => {
                let path = entry.path();
                if path.is_file() {
                    if !opts.binary && is_binary_file(path, opts.bin_check_bytes) {
                        if opts.skipped {
                            eprintln!("Skipped (binary): {}", path.display());
                        }
                        continue;
                    }
                    files_to_process.push(path.to_path_buf());
                }
            }
            Err(e) => {
                if opts.skipped {
                    eprintln!("Skipped (error): {}", e);
                }
            }
        }
    }

    if opts.fixed_order {
        files_to_process.sort();
    }

    let regex_matcher = if opts.regex {
        match Regex::new(&opts.keyword) {
            Ok(re) => Some(re),
            Err(e) => {
                eprintln!("Regex error: {}", e);
                process::exit(1);
            }
        }
    } else {
        None
    };

    let total_files = files_to_process.len();
    let stdout_lock = Arc::new(Mutex::new(()));

    let run_file = |path: &Path| -> usize {
        let content = match fs::read_to_string(path) {
            Ok(c) => c,
            Err(_) => return 0,
        };

        let mut file_matches = 0;
        let mut new_lines = Vec::new();
        let mut file_changed = false;

        let display_path = path.display().to_string();

        for (line_idx, line) in content.lines().enumerate() {
            let line_num = line_idx + 1;
            let mut matches_on_line = Vec::new();

            if let Some(ref re) = regex_matcher {
                for m in re.find_iter(line) {
                    matches_on_line.push((m.start(), m.end()));
                }
            } else {
                let mut start = 0;
                while let Some(pos) = line[start..].find(&opts.keyword) {
                    let match_start = start + pos;
                    let match_end = match_start + opts.keyword.len();
                    matches_on_line.push((match_start, match_end));
                    start = match_end;
                    if opts.keyword.is_empty() {
                        break;
                    }
                }
            }

            if !matches_on_line.is_empty() {
                file_matches += matches_on_line.len();

                if opts.is_ambs {
                    let mut formatted_line = String::new();
                    let mut last_idx = 0;
                    for &(m_start, m_end) in &matches_on_line {
                        formatted_line.push_str(&line[last_idx..m_start]);
                        let matched_str = &line[m_start..m_end];
                        if opts.color {
                            formatted_line.push_str(&matched_str.red().bold().to_string());
                        } else {
                            formatted_line.push_str(matched_str);
                        }
                        last_idx = m_end;
                    }
                    formatted_line.push_str(&line[last_idx..]);

                    let mut prefix = String::new();
                    if opts.file {
                        if opts.color {
                            prefix.push_str(&display_path.green().to_string());
                        } else {
                            prefix.push_str(&display_path);
                        }
                    }
                    if opts.row {
                        if !prefix.is_empty() { prefix.push(':'); }
                        let row_str = line_num.to_string();
                        if opts.color {
                            prefix.push_str(&row_str.yellow().to_string());
                        } else {
                            prefix.push_str(&row_str);
                        }
                    }
                    if opts.column {
                        if !prefix.is_empty() { prefix.push(':'); }
                        let col_str = (matches_on_line[0].0 + 1).to_string();
                        if opts.color {
                            prefix.push_str(&col_str.yellow().to_string());
                        } else {
                            prefix.push_str(&col_str);
                        }
                    }
                    if !prefix.is_empty() {
                        prefix.push(':');
                    }

                    let _guard = stdout_lock.lock().unwrap();
                    println!("{}{}", prefix, formatted_line);
                } else {
                    // ambr
                    if !opts.interactive {
                        let replaced_line = if let Some(ref re) = regex_matcher {
                            re.replace_all(line, &opts.replacement).to_string()
                        } else {
                            line.replace(&opts.keyword, &opts.replacement)
                        };
                        new_lines.push(replaced_line);
                        file_changed = true;
                    } else {
                        // Interactive
                        let mut replaced_line = line.to_string();
                        let _guard = stdout_lock.lock().unwrap();
                        print!("Replace in {}:{}: {} -> {}? [y/n/a/q] ", display_path, line_num, line, opts.replacement);
                        let _ = io::stdout().flush();
                        let mut input = String::new();
                        if io::stdin().read_line(&mut input).is_ok() {
                            let trimmed = input.trim().to_lowercase();
                            if trimmed == "y" || trimmed == "yes" || trimmed == "a" || trimmed == "all" {
                                replaced_line = if let Some(ref re) = regex_matcher {
                                    re.replace_all(line, &opts.replacement).to_string()
                                } else {
                                    line.replace(&opts.keyword, &opts.replacement)
                                };
                                file_changed = true;
                            }
                        }
                        new_lines.push(replaced_line);
                    }
                }
            } else if !opts.is_ambs {
                new_lines.push(line.to_string());
            }
        }

        if !opts.is_ambs && file_changed {
            let mut new_content = new_lines.join("\n");
            if content.ends_with('\n') {
                new_content.push('\n');
            }
            let _ = fs::write(path, new_content);
        }

        file_matches
    };

    let total_match_count: usize = files_to_process
        .into_iter()
        .map(|path| run_file(&path))
        .sum();

    if opts.statistics {
        let duration = start_time.elapsed();
        println!("{} files searched", total_files);
        println!("{} matches found", total_match_count);
        println!("{:.3} sec", duration.as_secs_f64());
    }

    if total_match_count > 0 {
        process::exit(0);
    } else {
        process::exit(1);
    }
}
EOF"}

