fn merge_config(target: &mut Config, source: Config) {
    if source.regex.is_some() { target.regex = source.regex; }
    if source.column.is_some() { target.column = source.column; }
    if source.row.is_some() { target.row = source.row; }
    if source.binary.is_some() { target.binary = source.binary; }
    if source.statistics.is_some() { target.statistics = source.statistics; }
