        .into_iter()
        .map(|path| run_file(&path))
        .sum();

    if opts.statistics {
        let duration = start_time.elapsed();
        println!("{} files searched", total_files);
        println!("{} matches found", total_match_count);
        println!("{:.3} sec", duration.as_secs_f64());
    }

    if total_match_count > 0 {
        process::exit(0);
    } else {
        process::exit(1);
    }
}
