                            }
                        }
                        new_lines.push(replaced_line);
                    }
                }
            } else if !opts.is_ambs {
                new_lines.push(line.to_string());
            }
        }

        if !opts.is_ambs && file_changed {
            let mut new_content = new_lines.join("\n");
            if content.ends_with('\n') {
                new_content.push('\n');
            }
            let _ = fs::write(path, new_content);
        }

        file_matches
    };

    let total_match_count: usize = files_to_process
        .into_iter()
        .map(|path| run_file(&path))
        .sum();

    if opts.statistics {
        let duration = start_time.elapsed();
        println!("{} files searched", total_files);
        println!("{} matches found", total_match_count);
        println!("{:.3} sec", duration.as_secs_f64());
    }

    if total_match_count > 0 {
        process::exit(0);
    } else {
        process::exit(1);
    }
}
